using Azure.Messaging.ServiceBus;using EnterpriseDocumentIntelligence.BuildingBlocks.Domain;using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;using System.Text.Json;using Microsoft.EntityFrameworkCore;
public sealed class ServiceBusClientFactory(IConfiguration c){readonly ServiceBusClient client=!string.IsNullOrWhiteSpace(c["ServiceBus:ConnectionString"])?new(c["ServiceBus:ConnectionString"]!):new(c["ServiceBus:FullyQualifiedNamespace"]!,new Azure.Identity.DefaultAzureCredential());public ServiceBusProcessor Create(string t,string s)=>client.CreateProcessor(t,s,new ServiceBusProcessorOptions{MaxConcurrentCalls=8,PrefetchCount=50,AutoCompleteMessages=false});}
public sealed class AuditWorker(ServiceBusClientFactory factory,DocumentDbContext db,ILogger<AuditWorker> log):BackgroundService{protected override async Task ExecuteAsync(CancellationToken ct){var p=factory.Create(Topics.AuditEvents,"audit-sub");p.ProcessMessageAsync+=Handle;p.ProcessErrorAsync+=Error;await p.StartProcessingAsync(ct);try{await Task.Delay(Timeout.Infinite,ct);}catch(OperationCanceledException){}finally{await p.StopProcessingAsync();await p.DisposeAsync();}}async Task Handle(ProcessMessageEventArgs a){try{var m=JsonSerializer.Deserialize<AuditRequested>(a.Message.Body.ToString(),new JsonSerializerOptions(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Invalid audit event");if(!await db.AuditEvents.AnyAsync(x=>x.Id==m.EventId,a.CancellationToken)){db.AuditEvents.Add(new AuditEvent(m.TenantId,m.ActorId,m.Action,m.ResourceType,m.ResourceId,m.Outcome,m.CorrelationId,m.MetadataJson,m.EventId));await db.SaveChangesAsync(a.CancellationToken);}await a.CompleteMessageAsync(a.Message);}catch(Exception ex){log.LogError(ex,"Audit event processing failed");if(a.Message.DeliveryCount>=5)await a.DeadLetterMessageAsync(a.Message,"max-delivery",ex.Message);else await a.AbandonMessageAsync(a.Message);}}Task Error(ProcessErrorEventArgs e){log.LogError(e.Exception,"Audit Service Bus error");return Task.CompletedTask;}}